// The brand files are generated by scripts/build-brand.mjs. These checks
// make sure the committed files match what the head tags promise and that
// their colors still match the design tokens.
import { readFileSync } from 'node:fs';
import sharp from 'sharp';
import { describe, expect, it } from 'vitest';
import { DEFAULT_SHARE_IMAGE } from '../../src/lib/seo';

const read = (file: string) => readFileSync(new URL(`../../${file}`, import.meta.url), 'utf8');
const file = (name: string) => new URL(`../../${name}`, import.meta.url).pathname;

const tokens = read('src/styles/tokens.css');
function token(name: string): string {
  const match = tokens.match(new RegExp(`--${name}:\\s*(#[0-9a-fA-F]{6})\\s*;`));
  if (!match) throw new Error(`--${name} is missing from tokens.css`);
  return match[1].toLowerCase();
}

interface ManifestIcon {
  src: string;
  sizes: string;
  type: string;
}

describe('web manifest', () => {
  const manifest = JSON.parse(read('public/site.webmanifest')) as {
    name: string;
    theme_color: string;
    background_color: string;
    icons: ManifestIcon[];
  };

  it('uses the brand colors from the tokens', () => {
    expect(manifest.theme_color).toBe(token('color-navy-900'));
    expect(manifest.background_color).toBe(token('color-white'));
  });

  it('lists icons that exist at the stated size', async () => {
    expect(manifest.icons.length).toBeGreaterThan(0);
    for (const icon of manifest.icons) {
      const { width, height, format } = await sharp(file(`public${icon.src}`)).metadata();
      expect(`${width}x${height}`).toBe(icon.sizes);
      expect(`image/${format}`).toBe(icon.type);
    }
  });
});

describe('head icons', () => {
  const layout = read('src/layouts/BaseLayout.astro');

  it('sets the browser theme color to the brand navy', () => {
    expect(layout).toContain(`<meta name="theme-color" content="${token('color-navy-900')}" />`);
  });

  it.each([
    ['public/favicon-32.png', 32, 32],
    ['public/apple-touch-icon.png', 180, 180],
    [`public${DEFAULT_SHARE_IMAGE.path}`, DEFAULT_SHARE_IMAGE.width, DEFAULT_SHARE_IMAGE.height],
  ])('%s is %i x %i', async (name, width, height) => {
    const meta = await sharp(file(name)).metadata();
    expect([meta.width, meta.height]).toEqual([width, height]);
  });

  it('links every generated icon', () => {
    for (const href of [
      '/favicon.svg',
      '/favicon-32.png',
      '/apple-touch-icon.png',
      '/site.webmanifest',
    ]) {
      expect(layout).toContain(`href="${href}"`);
    }
  });
});

describe('wordmark', () => {
  const svg = read('src/assets/brand/wordmark.svg');

  it('is drawn in the current text color so it works on navy and on photographs', () => {
    expect(svg).toContain('fill="currentColor"');
    expect(svg).not.toMatch(/#[0-9a-fA-F]{3,6}/);
  });

  it('is outlines only, so it needs no font to render', () => {
    expect(svg).not.toContain('<text');
  });
});
